INSERT INTO alternativas (id, questao_id, descricao, correta) VALUES
    ('e2e3162d-24a6-49c2-9905-cf7a5e2e4216', 'df641a99-c386-4240-ba1c-93fc8af748cc', $$
pepsina.
$$, false),
    ('98186f33-4f95-4d2a-a184-9a8022062aaa', 'df641a99-c386-4240-ba1c-93fc8af748cc', $$
tripsina.
$$, false),
    ('c7ee4173-7ae4-4902-8ac1-ca943ebac8bb', 'df641a99-c386-4240-ba1c-93fc8af748cc', $$
ptialina (amilase salivar).
$$, true),
    ('6016fa2e-bfef-4126-b73b-9e12eb50b9b1', 'df641a99-c386-4240-ba1c-93fc8af748cc', $$
lipase pancreática.
$$, false),
    ('14dfd23c-8d5b-4b0f-ab25-c2b2ffc10a54', '23de2e6c-ad0d-4dd6-8b6c-3bcca47e91c3', $$
contrações involuntárias e ondulatórias da musculatura lisa.
$$, true),
    ('0822501e-8f41-4ba9-9035-08294419e434', '23de2e6c-ad0d-4dd6-8b6c-3bcca47e91c3', $$
secreção de enzimas pelas glândulas anexas.
$$, false),
    ('f535a59e-3526-4743-aded-9252cd459751', '23de2e6c-ad0d-4dd6-8b6c-3bcca47e91c3', $$
absorção de nutrientes pelas vilosidades intestinais.
$$, false),
    ('60a28662-72e1-42f9-8054-28aeb684a365', '23de2e6c-ad0d-4dd6-8b6c-3bcca47e91c3', $$
abertura e fechamento da epiglote durante a deglutição.
$$, false),
    ('0bac307a-f1ac-4116-ab7b-934c06d35849', 'a163a013-0252-45f4-97a5-dbd1fe58ed01', $$
o gás carbônico passa do ar alveolar para o sangue, e o oxigênio, do sangue para o ar alveolar.
$$, false),
    ('be0aaa24-3f4d-4aa7-9668-a650cae3dd60', 'a163a013-0252-45f4-97a5-dbd1fe58ed01', $$
o oxigênio passa do ar alveolar para o sangue, e o gás carbônico, do sangue para o ar alveolar.
$$, true),
    ('17d4efcb-005c-4a3d-9120-b5e593e1cdd7', 'a163a013-0252-45f4-97a5-dbd1fe58ed01', $$
o nitrogênio é absorvido pelos capilares sanguíneos.
$$, false),
    ('5cbf9fa9-b124-4868-90ff-18fabec73a00', 'a163a013-0252-45f4-97a5-dbd1fe58ed01', $$
a hemoglobina é convertida em fibrinogênio.
$$, false),
    ('a6455b34-a4f1-4782-a354-5aba26898671', '68eeb5ee-4e6a-4f87-8c19-518f2f9454ab', $$
arterial, vindo dos pulmões, e o bombeia para o corpo.
$$, false),
    ('26d4a18d-b091-4001-ae0a-e2f1954b2f6e', '68eeb5ee-4e6a-4f87-8c19-518f2f9454ab', $$
venoso, vindo do corpo, e o bombeia para os pulmões.
$$, true),
    ('842589ae-e77c-4bb5-a32e-5a8eb6e89023', '68eeb5ee-4e6a-4f87-8c19-518f2f9454ab', $$
arterial, vindo do corpo, e o bombeia para os pulmões.
$$, false),
    ('e1202667-4dc4-4b08-9c8a-233d194fe11f', '68eeb5ee-4e6a-4f87-8c19-518f2f9454ab', $$
venoso, vindo dos pulmões, e o bombeia para o corpo.
$$, false),
    ('4ea3da10-7c12-4948-aef7-cbf7979bed3f', '94e1d3b6-b9e4-4445-963a-04793cbdcaf9', $$
paredes finas, válvulas e conduzir sangue em direção ao coração.
$$, false),
    ('69fa0215-a4dc-41a5-8813-396497a2153f', '94e1d3b6-b9e4-4445-963a-04793cbdcaf9', $$
paredes espessas, elásticas e conduzir sangue do coração para os tecidos.
