    ('44e66fa5-4418-467b-9b8c-ea12d4ffddf7', 'd0935648-894d-4784-a60a-1427bfcbc5fd', $$
membrana plasmática.
$$, false),
    ('7c4594a7-c2e6-47cb-aa68-8f98c4df836a', 'd0935648-894d-4784-a60a-1427bfcbc5fd', $$
envoltório nuclear (carioteca).
$$, true),
    ('cefef277-a3ad-4adb-becd-45031767d120', 'd0935648-894d-4784-a60a-1427bfcbc5fd', $$
ribossomos.
$$, false),
    ('0579f084-c88a-4cca-b3c7-d4b7ec702ee8', 'df3181e8-c932-4a56-9d3d-d5e9fa537a58', $$
na presença de flagelos.
$$, false),
    ('d22414b6-2ce1-43d5-88e9-9677a1737fa6', 'df3181e8-c932-4a56-9d3d-d5e9fa537a58', $$
na composição da parede celular.
$$, true),
    ('75a6b338-f0af-4177-8312-f46d5fa908ea', 'df3181e8-c932-4a56-9d3d-d5e9fa537a58', $$
no tipo de material genético.
$$, false),
    ('13fea987-ec74-457f-a529-ddf2435ac76d', 'df3181e8-c932-4a56-9d3d-d5e9fa537a58', $$
na capacidade de formar endósporos.
$$, false),
    ('ffd637e4-5355-4d35-8868-6c78bac5acc5', '8b42c1a0-4e76-44c4-9185-45016b35ecb5', $$
