INSERT INTO alternativas (id, questao_id, descricao, correta) VALUES
    ('6c79ee82-d82c-4509-af8e-de3e3f78b346', '0d0c017f-478c-4507-b7ee-51a99390dd28', $$
a luz incidente tem qualquer intensidade, independentemente da frequência.
$$, false),
    ('cbb08378-4b5c-442e-8a77-2d01c9723f07', '0d0c017f-478c-4507-b7ee-51a99390dd28', $$
