INSERT INTO questoes (id, conteudo_id, num_questao, enunciado) VALUES
    ('790749e8-b87f-43fe-bba2-e0bec92dbf18', 'ee4f8c6a-548c-42b5-9a84-b9ef9f8fbc62', 1, $$
